def json_dumps(item, default_mapping=None, force_use_builtin_json: bool=
    False, **kwargs):
    if orjson is not None and not force_use_builtin_json:
        convertor = json_convertor_default(default_mapping)
        return orjson.dumps(item, default=convertor, **kwargs)
    else:
        convertor = json_convertor_default(default_mapping)
        return json.dumps(item, default=convertor, **kwargs)


def object_hook(self, obj):
    if 'old_type' in obj and 'new_type' in obj:
        for type_key in ('old_type', 'new_type'):
            type_str = obj[type_key]
            obj[type_key] = TYPE_STR_TO_TYPE.get(type_str, type_str)

    return obj
